fn fibonacci(n: usize) -> Vec<i32> {
    let mut fib_sequence = Vec::with_capacity(n);
    
    // Base cases
    fib_sequence.push(0); // F(0)
    fib_sequence.push(1); // F(1)

    // Calculate Fibonacci numbers from F(2) to F(n-1)
    for i in 2..n {
        let next_fib = fib_sequence[i - 1] + fib_sequence[i - 2];
        fib_sequence.push(next_fib);
    }

    fib_sequence
}